int main(){try{
    Fixture f;need(f.valid(),"empty enabled claim state validates");need(validate_visit_reception_layout({{"visit_reception_intents","1"},{"visit_reception_claims","1"}},&f.intents,&f.messages).ok,"exact pair admits");need(!validate_visit_reception_layout({{"visit_reception_intents","1"}},&f.intents,&f.messages).ok,"missing claims marker rejects");need(!validate_visit_reception_layout({{"visit_reception_claims","1"}},&f.intents,&f.messages).ok,"orphan claims marker rejects");need(!validate_visit_reception_layout({{"visit_reception_intents","1"},{"visit_reception_claims","2"}},&f.intents,&f.messages).ok,"unknown claims version rejects");
    need(!f.bind().ok,"no real session cannot claim");auto session=f.open();need(f.bind().ok&&f.valid(),"fresh exact session gets one immutable claim");const auto claim=f.state.claims.rows().front().first;need(read_visit_reception_claim(f.state,session,"recipient","recipient_intent")!=nullptr,"exact claim pure read permits");need(!read_visit_reception_claim(f.state,session,"sender","recipient_intent"),"another actor cannot reuse claim");need(!read_visit_reception_claim(f.state,session,"recipient","other_intent"),"another intent cannot reuse claim");auto next=f.common.state().next_instance_id;need(!f.bind().ok&&f.common.state().next_instance_id==next&&f.state.claims.size()==1,"new rebind fails without ID or fact");
    auto original=f.state;f.state.claims.find(claim)->actor_id="sender";rebuild_visit_reception_indexes(f.state);need(!f.valid(),"forged actor with rebuilt index rejects");f.state=original;f.state.claims.find(claim)->session_id="interaction:2";rebuild_visit_reception_indexes(f.state);need(!f.valid(),"forged session cannot reuse same allocated claim");f.state=original;f.state.claims.find(claim)->provider_actor_id="sender";need(!f.valid(),"forged historical provider rejects");f.state=original;
    f.interactions.interactions.front().context.place_id="elsewhere";need(!f.valid(),"current same session must retain original location context");f.interactions.interactions.front().context.place_id="hall";f.common.state().facts.erase(claim);need(!f.valid(),"missing Common source rejects");need(f.common.append_fact({claim,visit_reception_claim_kind,visit_reception_claim_module}).ok&&f.valid(),"restoring exact original header validates");f.state.by_session.clear();need(!f.valid(),"stale or forged derived source index rejects");f.state=original;
    f.interactions.interactions.clear();f.common.state().roles.find("desk")->actor_id="sender";f.common.state().actors.find("custodian")->alive=false;need(f.valid(),"later ordinary End, role change and death preserve original source");
    auto json=encode_visit_reception_claims(f.state);auto decoded=decode_visit_reception_claims(json);need(decoded.ok&&compare_boundary(json,encode_visit_reception_claims(decoded.value)).exact(),"independent JSON exact roundtrip");auto duplicate=json;duplicate.as<BoundaryValue::Dict>()->push_back({"version",BoundaryValue{Integer{1}}});need(!decode_visit_reception_claims(duplicate).ok,"typed JSON duplicate field rejects");auto badversion=f.state;badversion.version=2;need(!decode_visit_reception_claims(encode_visit_reception_claims(badversion)).ok,"unsupported typed JSON version rejects");
    CodecVisitor::Buffer bytes;auto copy=f.state;CodecVisitor writer(bytes);need(visit_visit_reception_checkpoint(writer,copy).ok&&writer.finish().ok,"independent binary write succeeds");const auto saved=bytes;VisitReceptionState restored;CodecVisitor reader(saved);need(visit_visit_reception_checkpoint(reader,restored).ok&&reader.finish().ok&&compare_boundary(json,encode_visit_reception_claims(restored)).exact(),"independent binary exact roundtrip");bytes.push_back(0);const auto trailing=bytes;CodecVisitor extra(trailing);VisitReceptionState ignored;need(visit_visit_reception_checkpoint(extra,ignored).ok&&!extra.finish().ok,"binary trailing junk rejects");
    Fixture wrong_place;wrong_place.open();wrong_place.interactions.interactions.front().context.place_id="elsewhere";need(!wrong_place.bind().ok&&wrong_place.state.claims.empty(),"writer itself rejects mismatched place before append");
    Fixture old;old.open();need(old.common.next_id("unrelated").ok&&!old.bind().ok,"later unrelated allocation cannot retroactively claim old meeting");
    Fixture rollback;auto before=rollback.common.state().next_instance_id;auto mark=rollback.common.begin_savepoint();need(mark.ok,"original Common savepoint opens");rollback.open();need(rollback.bind().ok&&!rollback.state.claims.empty(),"actual claim and fact append before caller failure");need(rollback.common.rollback_savepoint(mark.value).ok,"original Common rollback succeeds");rollback.state=VisitReceptionState{};rollback.interactions=InteractionState{};need(rollback.common.state().facts.empty()&&rollback.common.state().next_instance_id==before&&rollback.state.claims.empty(),"explicit owner copies restore claim together with Common; whole World pending");
    Fixture limit;limit.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;auto late=limit.common.begin_savepoint();need(late.ok,"late allocation savepoint opens");limit.open();auto failed=limit.bind();need(!failed.ok&&failed.error.original.code=="InstanceIdOverflow"&&limit.state.claims.empty()&&limit.common.state().facts.empty(),"claim ID overflow after original session allocates no claim");need(limit.common.rollback_savepoint(late.value).ok,"late original session allocation rolls back");
    std::cout<<checks<<" pure visit reception claim checks, 0 failures; Talk/World/GUI not run\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
